由于g_{\tau}(t)\longleftrightarrow\tau Sa(\frac{\tau}{2}\omega) \\
\tau Sa(\frac{\tau}{2}t)\longleftrightarrow2\pi g_{\tau}(-\omega)=2\pi g_{\tau}(\omega)
\end{aligned}
